const { getCookieHeader, hasCookie } = require('./index')

const logger = require('./logger')

// domain 参数决定带着 cookie 的请求发往哪里, 只允许网易自己的 https 域名
const ALLOWED_DOMAIN_SUFFIXES = ['163.com', '126.net', '127.net']

const sanitizeDomain = (domain) => {
  if (!domain) return ''
  try {
    const { protocol, hostname, origin } = new URL(domain)
    const allowed = ALLOWED_DOMAIN_SUFFIXES.some(
      (suffix) => hostname === suffix || hostname.endsWith('.' + suffix),
    )
    if (protocol === 'https:' && allowed) return origin
  } catch (e) {
    // 非法 URL, 按不允许处理
  }
  logger.warn('已忽略不在白名单内的 domain 参数:', String(domain))
  return ''
}

const createOption = (query, crypto = '') => {
  const headerCookie = getCookieHeader(query.headers)

  return {
    crypto: query.crypto || crypto || '',
    cookie: hasCookie(query.cookie)
      ? query.cookie
      : hasCookie(headerCookie)
      ? headerCookie
      : process.env.NETEASE_COOKIE,
    ua: query.ua || '',
    proxy: query.proxy,
    realIP: query.realIP,
    randomCNIP:
      process.env.ENABLE_RANDOM_CN_IP === 'true'
        ? !['false', false].includes(query.randomCNIP)
        : ['true', true].includes(query.randomCNIP),
    e_r: query.e_r || undefined,
    domain: sanitizeDomain(query.domain),
    checkToken: query.checkToken || false,
    headers: query.headers || {},
    timeout: query.timeout || 0,
  }
}
module.exports = createOption
